// One-off generator: mirrors topic-bank-sources.mjs (the canonical shared
// source) into shared/topic-bank-sources.js, a plain non-module <script>
// the browser tools (notes-factory, question-factory, update-factory,
// reporting) load directly — so there is exactly one hand-maintained copy
// of TOPIC_BANK_SOURCES, never four.
// Re-run this any time topic-bank-sources.mjs changes; do not hand-edit the
// generated file.
//
//   node Automation/core/src/gen-topic-bank-sources-browser.mjs

import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const REPO_ROOT = path.resolve(__dirname, '..', '..', '..');
const src = fs.readFileSync(path.join(__dirname, 'topic-bank-sources.mjs'), 'utf8');

const body = src.replace(/^export /gm, '');

const out = `// AUTO-GENERATED by gen-topic-bank-sources-browser.mjs from
// Automation/core/src/topic-bank-sources.mjs. Do not hand-edit — re-run the
// generator instead so this never drifts from the canonical source.
// Exposes window.TopicBankSources = { TOPIC_BANK_SOURCES }.
(function(global){
${body}
global.TopicBankSources = { TOPIC_BANK_SOURCES };
})(typeof window !== 'undefined' ? window : this);
`;

const outDir = path.join(REPO_ROOT, 'shared');
fs.mkdirSync(outDir, { recursive: true });
fs.writeFileSync(path.join(outDir, 'topic-bank-sources.js'), out);
console.log('wrote shared/topic-bank-sources.js');
